<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $workOrder->work_order_no }} · Service Report · UNIFCO</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:'Cairo',sans-serif;--navy:#06275c;--navy2:#071f4d;--red:#e20b24;--green:#168a55;--bg:#f5f7fa;--line:#dfe6ee;--muted:#708095}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--navy2)}a{text-decoration:none;color:inherit}.top{height:70px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 28px;gap:10px}.brand{font-size:20px;font-weight:900}.spacer{flex:1}.btn{padding:9px 13px;border-radius:8px;background:var(--navy);color:#fff;font-size:10px;font-weight:800}.btn.secondary{background:#edf3f8;color:var(--navy)}.wrap{max-width:1250px;margin:auto;padding:22px}.hero{background:linear-gradient(135deg,#071f4d,#123d72);color:#fff;border-radius:16px;padding:22px}.hero h1{margin:5px 0;font-size:24px}.hero p{margin:0;color:#ccd9e9;font-size:10px}.badge{display:inline-flex;padding:4px 8px;border-radius:999px;background:#ffffff18;font-size:9px}.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:14px 0}.kpi,.box{background:#fff;border:1px solid var(--line);border-radius:12px}.kpi{padding:14px}.kpi b{display:block;font-size:18px}.kpi span{font-size:8px;color:var(--muted)}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.box{padding:17px}.box h3{margin:0 0 12px;font-size:14px}.table{width:100%;border-collapse:collapse;font-size:10px}.table th,.table td{padding:9px;border-bottom:1px solid #edf1f5;text-align:left}.table th{font-size:9px;color:var(--muted)}.pill{padding:4px 7px;border-radius:999px;background:#e8f6ef;color:#176a43;font-size:8px}.pill.fail{background:#fdebed;color:#b42239}.evidence{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.file{padding:10px;background:#f7f9fc;border-radius:8px;border:1px solid #e4eaf0;font-size:9px}.summary{white-space:pre-wrap;font-size:10px;line-height:1.8}@media(max-width:800px){.kpis{grid-template-columns:repeat(2,1fr)}.grid2{grid-template-columns:1fr}.evidence{grid-template-columns:1fr 1fr}}@media(max-width:480px){.kpis,.evidence{grid-template-columns:1fr}.wrap{padding:12px}}</style></head><body><header class="top"><div class="brand">UNIFCO</div><div class="spacer"></div><a class="btn secondary" href="{{ route('customer.asset.show',$workOrder->asset) }}">Asset 360</a><a class="btn secondary" href="{{ route('customer.section','work-orders') }}">Work Orders</a></header><main class="wrap"><section class="hero"><span class="badge">CUSTOMER SERVICE REPORT · تقرير خدمة العميل</span><h1>{{ $workOrder->work_order_no }}</h1><p>{{ $workOrder->asset?->asset_code }} · {{ $workOrder->asset?->name }} · {{ $workOrder->asset?->site?->name ?: 'No site' }} · {{ $workOrder->maintenance_type }} · {{ $workOrder->priority }}</p></section><section class="kpis"><div class="kpi"><b>{{ $workOrder->status }}</b><span>Status · الحالة</span></div><div class="kpi"><b>{{ $workOrder->planned_start?->format('Y-m-d') ?: '—' }}</b><span>Planned Date</span></div><div class="kpi"><b>{{ $workOrder->started_at?->format('Y-m-d H:i') ?: '—' }}</b><span>Started</span></div><div class="kpi"><b>{{ $workOrder->completed_at?->format('Y-m-d H:i') ?: '—' }}</b><span>Completed</span></div><div class="kpi"><b>{{ $workOrder->downtime_minutes ?: 0 }} min</b><span>Downtime</span></div></section><div class="grid2"><section class="box"><h3>Maintenance Checklist · قائمة الفحص</h3><table class="table"><thead><tr><th>Task</th><th>Result</th><th>Reading</th><th>Completed</th></tr></thead><tbody>@forelse($tasks as $t)<tr><td>{{ $t->task_title }}</td><td><span class="pill {{ $t->result_status==='FAIL'?'fail':'' }}">{{ $t->result_status ?: 'PENDING' }}</span></td><td>{{ $t->numeric_value ?? $t->text_value ?? '—' }} {{ $t->unit }}</td><td>{{ $t->completed_at ?: '—' }}</td></tr>@empty<tr><td colspan="4">No checklist attached.</td></tr>@endforelse</tbody></table></section><section class="box"><h3>Spare Parts Used · قطع الغيار المستخدمة</h3><table class="table"><thead><tr><th>Part</th><th>Description</th><th>Quantity</th></tr></thead><tbody>@forelse($materials as $m)<tr><td>{{ $m->item_code }}</td><td>{{ $m->item_name }}</td><td>{{ $m->quantity }} {{ $m->uom }}</td></tr>@empty<tr><td colspan="3">No parts used.</td></tr>@endforelse</tbody></table><p style="font-size:9px;color:var(--muted);margin-top:10px">Internal UNIFCO purchasing costs and labor costing are intentionally not displayed in the customer portal.</p></section></div><div class="grid2"><section class="box"><h3>Failure / Corrective Action · العطل والإجراء التصحيحي</h3>@forelse($failures as $f)<div style="padding:9px 0;border-bottom:1px solid #edf1f5"><strong style="font-size:10px">{{ $f->failure_mode }} · {{ $f->severity }}</strong><div style="font-size:9px;color:var(--muted)">{{ $f->failed_at }} → {{ $f->restored_at ?: 'Open' }} · {{ $f->downtime_minutes }} min</div><div class="summary">{{ $f->failure_effect }}
{{ $f->corrective_action }}</div></div>@empty<p>No failure event linked to this work order.</p>@endforelse</section><section class="box"><h3>Completion Summary · ملخص التنفيذ</h3><div class="summary">{{ $workOrder->completion_notes ?: $workOrder->execution_notes ?: 'Work is still in progress.' }}</div></section></div><section class="box" style="margin-top:14px"><h3>Maintenance Evidence · الصور الداعمة</h3><div class="evidence">@forelse($attachments as $a)<a class="file" href="{{ route('customer.work-orders.attachments.download',[$workOrder,$a->id]) }}"><strong>{{ $a->attachment_type }}</strong><br>{{ $a->title ?: $a->original_name }}</a>@empty<p>No customer-visible evidence attached.</p>@endforelse</div></section></main></body></html>